from fractions import Fraction
import json

def window_metrics(events,start,end):
    # Own terminal observation records:(observed_at_ms,known_duration_ms_or_None,outcome).
    if type(events) is not list or len(events)>256 or any(type(x) is not int for x in (start,end)) or not 0<=start<end:
        raise ValueError('invalid telemetry window')
    for row in events:
        if type(row) is not tuple or len(row)!=3:raise ValueError('invalid observation schema')
        at,duration,outcome=row
        if type(at) is not int or not 0<=at<=10**9 or type(outcome) is not str or outcome not in ('ok','error','timeout'):
            raise ValueError('invalid observation fields')
        if outcome=='timeout':
            if duration is not None:raise ValueError('timeout latency unknown in this schema')
        elif type(duration) is not int or not 0<=duration<=min(at,10**6):
            raise ValueError('invalid known duration')
    selected=[row for row in events if start<=row[0]<end]
    durations=sorted(row[1] for row in selected if row[1] is not None)
    count=len(selected);bad=sum(row[2]!='ok' for row in selected)
    bins=[0,0,0,0]
    for value in durations:
        bucket=next((i for i,boundary in enumerate((10,100,1000)) if value<=boundary),3)
        bins[bucket]+=1
    return {'schema':1,'window_ms':(start,end),'events':count,'bad':bad,
            'bad_ratio':Fraction(bad,count) if count else None,
            'known_latency_events':len(durations),'unknown_latency_events':count-len(durations),
            'p95_known_ms':durations[(95*len(durations)+99)//100-1] if durations else None,
            'noncumulative_histogram_le_10_100_1000_over_ms':tuple(bins)}

def error_alert(events,start,end,min_events,max_bad_ratio):
    # Own error-only teaching rule. Recompute from validated raw observations.
    metrics=window_metrics(events,start,end)
    if type(min_events) is not int or min_events<1 or type(max_bad_ratio) is not Fraction or not 0<=max_bad_ratio<=1:
        raise ValueError('invalid alert rule')
    if metrics['events']==0:return 'no-data'
    if metrics['events']<min_events:return 'insufficient-data'
    return 'alert' if metrics['bad_ratio']>max_bad_ratio else 'within-error-threshold'

events=[(100,10,'ok'),(200,100,'error'),(300,None,'timeout'),(1400,1000,'ok')]
m=window_metrics(events,0,400)
print(m['events'],m['bad'],m['bad_ratio'])
print(m['known_latency_events'],m['unknown_latency_events'],m['p95_known_ms'])
print(m['noncumulative_histogram_le_10_100_1000_over_ms'])
print(error_alert(events,0,400,5,Fraction(1,10)))
print(error_alert(events,0,400,3,Fraction(1,10)))
print(error_alert([],0,400,3,Fraction(1,10)))
